import { useEffect, useRef } from "react";
import { motion } from "framer-motion";
import { portfolioData } from "../data/portfolio";

export default function Hero() {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: -999, y: -999 });
  const radiusRef = useRef(0);
  const targetRadiusRef = useRef(0);
  const rafRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();
    window.addEventListener("resize", resize);

    const draw = () => {
      radiusRef.current += (targetRadiusRef.current - radiusRef.current) * 0.07;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const { x, y } = mouseRef.current;
      const r = radiusRef.current;

      if (r > 1) {
        // outer glow
        const grd = ctx.createRadialGradient(x, y, 0, x, y, r);
        grd.addColorStop(0, "rgba(78,154,241,0.12)");
        grd.addColorStop(0.5, "rgba(78,154,241,0.05)");
        grd.addColorStop(1, "rgba(78,154,241,0)");
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fillStyle = grd;
        ctx.fill();

        // inner ring
        ctx.beginPath();
        ctx.arc(x, y, r * 0.55, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(78,154,241,${0.28 * (r / 180)})`;
        ctx.lineWidth = 1;
        ctx.stroke();

        // outer ring
        ctx.beginPath();
        ctx.arc(x, y, r * 0.88, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(78,154,241,${0.12 * (r / 180)})`;
        ctx.lineWidth = 1;
        ctx.stroke();

        // eye icon hint
        ctx.font = `${14 * (r / 180)}px serif`;
        ctx.fillStyle = `rgba(78,154,241,${0.5 * (r / 180)})`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText("◉", x, y);
      }

      rafRef.current = requestAnimationFrame(draw);
    };
    rafRef.current = requestAnimationFrame(draw);

    return () => {
      window.removeEventListener("resize", resize);
      cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const handleMouseMove = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    mouseRef.current = { x: e.clientX - rect.left, y: e.clientY - rect.top };
    targetRadiusRef.current = 180;
  };
  const handleMouseLeave = () => { targetRadiusRef.current = 0; };

  const { heroLines, heroAccentWord, heroBio, heroRoles, stack } = portfolioData;

  return (
    <section
      id="hero"
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{
        height: "100vh", position: "relative",
        overflow: "hidden", display: "flex",
        flexDirection: "column", justifyContent: "flex-end",
      }}
    >
      {/* Background */}
      <div style={{
        position: "absolute", inset: 0,
        background: `
          radial-gradient(ellipse at 65% 35%, rgba(78,154,241,0.07) 0%, transparent 55%),
          radial-gradient(ellipse at 20% 75%, rgba(230,185,128,0.05) 0%, transparent 50%),
          var(--bg)
        `,
      }} />

      {/* Grid */}
      <div style={{
        position: "absolute", inset: 0, opacity: 0.025,
        backgroundImage:
          "linear-gradient(var(--text) 1px, transparent 1px), linear-gradient(90deg, var(--text) 1px, transparent 1px)",
        backgroundSize: "90px 90px",
      }} />

      {/* Canvas reveal */}
      <canvas
        ref={canvasRef}
        style={{
          position: "absolute", inset: 0,
          width: "100%", height: "100%",
          pointerEvents: "none",
        }}
      />

      {/* Profile Image */}
      <motion.div
        initial={{ opacity: 0, x: 30 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 1, delay: 0.7 }}
        className="hero-portrait"
      >
        <img
          src="/images/harsh.png"
          alt="Harsh Singh"
        />
      </motion.div>

      {/* Content */}
      <div style={{ position: "relative", zIndex: 2, padding: "0 4vw 40px" }}>
        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7, delay: 0.3, ease: [0.16, 1, 0.3, 1] }}
          style={{
            fontSize: 11, letterSpacing: "3px",
            textTransform: "uppercase", color: "var(--accent)",
            marginBottom: 20,
            fontFamily: "var(--font-body)",
          }}
        >
          // COMPUTER SCIENCE | SOFTWARE DEVELOPMENT — {stack}
        </motion.p>

        <motion.h1
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.9, delay: 0.5, ease: [0.16, 1, 0.3, 1] }}
          style={{
            fontFamily: "var(--font-disp)",
            fontSize: "clamp(60px, 11vw, 130px)",
            lineHeight: 0.88,
            letterSpacing: "2px",
            color: "var(--text)",
          }}
        >
          {heroLines.map((line, i) => (
            <span key={i} style={{ display: "block" }}>
              {line === heroAccentWord
                ? <span style={{ color: "var(--accent)" }}>{line}</span>
                : line}
            </span>
          ))}
        </motion.h1>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.85, ease: [0.16, 1, 0.3, 1] }}
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-end",
            marginTop: 36,
            paddingTop: 36,
            borderTop: "1px solid var(--border)",
          }}
          className="hero-sub"
        >
          <p style={{
            maxWidth: 440, fontSize: 15, lineHeight: 1.75,
            color: "var(--text-muted)", letterSpacing: "0.3px",
          }}>
            {heroBio}
          </p>
          <div style={{ textAlign: "right" }}>
            {heroRoles.map((r, i) => (
              <span key={i} style={{
                display: "block", fontSize: 12,
                letterSpacing: "2px", textTransform: "uppercase",
                color: "var(--text-dim)", marginBottom: 4,
              }}>{r}</span>
            ))}
          </div>
        </motion.div>
      </div>

      {/* Scroll indicator */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.8, delay: 1.3 }}
        style={{
          position: "absolute", bottom: 40,
          left: "50%", transform: "translateX(-50%)",
          display: "flex", flexDirection: "column",
          alignItems: "center", gap: 8, zIndex: 2,
        }}
      >
        <span style={{
          fontSize: 10, letterSpacing: "3px",
          textTransform: "uppercase", color: "var(--text-dim)",
        }}>Scroll</span>
        <motion.div
          animate={{ scaleY: [1, 0.4, 1], opacity: [0.6, 1, 0.6] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
          style={{
            width: 1, height: 48,
            background: "linear-gradient(to bottom, var(--accent), transparent)",
            transformOrigin: "top",
          }}
        />
      </motion.div>

      <style>{`
        @media (max-width: 768px) {
          .hero-sub { flex-direction: column; gap: 24px; align-items: flex-start !important; }
          .hero-sub > div { text-align: left !important; }
        }
          .hero-portrait {
  position: absolute;
  z-index: 1;
  top: 12%;
  right: 8%;
  width: clamp(280px, 30vw, 420px);
  height: clamp(380px, 43vw, 560px);
  overflow: hidden;
  border-radius: 180px 180px 12px 12px;
  isolation: isolate;
}

.hero-portrait img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  display: block;
}

/* Blend portrait edges into the background */
.hero-portrait::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(
      ellipse at center,
      transparent 48%,
      rgba(15, 17, 23, 0.35) 75%,
      rgba(15, 17, 23, 0.95) 100%
    ),
    linear-gradient(
      to bottom,
      transparent 65%,
      rgba(15, 17, 23, 1) 100%
    );
}

@media (max-width: 768px) {
  .hero-portrait {
    width: 150px;
    height: 190px;
    top: 13%;
    right: 5%;
    opacity: 0.65;
  }
}
      `}</style>
    </section>
  );
}
